/**
 * City configuration for the frontend.
 *
 * Reads a build-time mirror of config/cities/<slug>.json, the same file the
 * pipelines load (issue #68). One config, so the map centre the browser flies
 * to and the bbox the pipeline validates its grid against cannot drift apart.
 *
 * The mirror under ./cities/ exists because Turbopack will not import a module
 * from outside the Next.js root, and reading it at runtime would stall the map
 * on a fetch for data that never changes between deploys. It is generated by
 * pipeline/sync_city_config.py and CI fails if it has drifted.
 *
 * This deployment publishes Nagpur, and only Nagpur. `frontend/public/` holds
 * one city's dataset at a time, so ACTIVE_CITY has to name the city whose files
 * are actually there: pointing it elsewhere would centre the map on one city
 * and draw another.
 */

import mumbai from "./cities/mumbai.json";
import nagpur from "./cities/nagpur.json";

export type CityConfig = {
  slug: string;
  name: string;
  /** Map centre as [lat, lon], the order Leaflet takes. */
  center: [number, number];
  zoom: number;
  /** [min_lon, min_lat, max_lon, max_lat], WGS84. */
  bbox: [number, number, number, number];
  lat: number;
  lon: number;
  timezone: string;
  /** Side of one analysis cell, in metres. */
  cellSizeM: number;
  /** The same, as it reads in a sentence: "500 m", "1 km". */
  cellLabel: string;
};

type RawCityConfig = {
  slug: string;
  name: string;
  timezone: string;
  bbox: number[];
  map: { center: number[]; zoom?: number };
  grid?: { cell_size_m?: number };
};

function toCityConfig(raw: RawCityConfig): CityConfig {
  const [lat, lon] = raw.map.center;
  const cellSizeM = raw.grid?.cell_size_m ?? 1000;
  return {
    slug: raw.slug,
    name: raw.name,
    center: [lat, lon],
    zoom: raw.map.zoom ?? 11,
    bbox: raw.bbox as [number, number, number, number],
    // `lat`/`lon` are kept as flat fields because the live-weather widget takes
    // a point rather than a map view, and it read them off this shape before
    // the config existed.
    lat,
    lon,
    timezone: raw.timezone,
    cellSizeM,
    cellLabel: cellSizeM >= 1000 && cellSizeM % 1000 === 0 ? `${cellSizeM / 1000} km` : `${cellSizeM} m`,
  };
}

export const MUMBAI: CityConfig = toCityConfig(mumbai as RawCityConfig);
export const NAGPUR: CityConfig = toCityConfig(nagpur as RawCityConfig);

/** The city this deployment is showing. */
export const ACTIVE_CITY: CityConfig = NAGPUR;

/**
 * What the areas the index is rolled up into are called, and how one is named.
 *
 * Mumbai's are BMC wards, known by a code: "Ward K/E". Nagpur's are approximate
 * localities built around OpenStreetMap place names, because no open ward map
 * exists (pipeline/open/01_localities.mjs), and they are known by the name
 * itself: "Sitabuldi", not "Ward Sitabuldi". Calling them wards would claim an
 * administrative standing they do not have.
 */
export const AREA = {
  singular: "locality",
  plural: "localities",
  /** Sentence-initial forms. */
  Singular: "Locality",
  Plural: "Localities",
} as const;

/** How one area is referred to in copy. */
export function areaName(id: string): string {
  return id;
}

/** Stated wherever the areas are introduced, so they are never mistaken for administrative units. */
export const AREA_CAVEAT =
  "Localities are approximate: each cell is grouped with the nearest named place from OpenStreetMap. They are not NMC zones or wards.";

/** Publication metadata belongs beside the mirrored city configs. */
export const CITY_REGISTRY = [
  {
    ...NAGPUR,
    country: "India",
    published: true,
    lastRefreshed: null as string | null,
    maintainer: "UrbanCanopy",
    note: "Open-data build. Plantability is not yet ecologically calibrated for central India.",
  },
];
